149:     private String evaluate(CompositeStringExpression compositeStringExpression, Map<String, ?> context) {
150:         StringBuilder sb = new StringBuilder();
151:         Expression[] subExpressions = compositeStringExpression.getExpressions();
152: 
153:         for (Expression subExpression : subExpressions) {
154:             if (subExpression instanceof LiteralExpression) {
155:                 sb.append(subExpression.getValue());
156: 
157:                 continue;
158:             } else if (subExpression instanceof SpelExpression) {
159:                 sb.append(evaluate(ACCESSOR_PREFIX + subExpression.getExpressionString() + ACCESSOR_SUFFIX, context));
160: 
161:                 continue;
162:             }
163: 
164:             Class<? extends Expression> subExpressionClass = subExpression.getClass();
165: 
166:             throw new IllegalArgumentException("unknown expression type: " + subExpressionClass.getName());
167:         }
168: 
169:         return sb.toString();
170:     }
171: 
172:     @Nullable
173:     private Object evaluate(Object value, Map<String, ?> context) {
174:         if (value instanceof String string) {
175:             Expression expression;
176:             boolean formulaExpression = false;
177: 
178:             string = string.trim();
179: 
180:             if (string.equals(FORMULA_PREFIX)) {
181:                 return string;
182:             }
183: 
184:             if (string.startsWith(FORMULA_PREFIX)) {
185:                 formulaExpression = true;
186: 
187:                 try {
188:                     string = string.replaceAll("\\$\\{([^}]*)}", "$1");
189: 
190:                     if (!validateFormulaExpression(string)) {
191:                         throw new UnsupportedOperationException("Invalid formula expression: " + string);
192:                     }
193: 
194:                     expression = expressionParser.parseExpression(string.substring(1));
195:                 } catch (ParseException e) {
196:                     throw new IllegalArgumentException("Invalid formula expression: " + string, e);
197:                 }
198:             } else {
199:                 if (!validateTextExpression(string)) {
200:                     throw new IllegalArgumentException("Invalid expression: " + string);
201:                 }
202: 
203:                 expression = expressionParser.parseExpression(
204:                     string, new TemplateParserContext(ACCESSOR_PREFIX, ACCESSOR_SUFFIX));
205:             }
206: 
207:             if (expression instanceof CompositeStringExpression) { // attempt partial evaluation
208:                 return evaluate((CompositeStringExpression) expression, context);
209:             } else if (expression instanceof LiteralExpression) {
210:                 return expression.getValue();
211:             } else {
212:                 try {
213:                     return expression.getValue(createEvaluationContext(context, formulaExpression));
214:                 } catch (SpelEvaluationException e) {
215:                     if (logger.isTraceEnabled()) {
216:                         logger.trace(e.getMessage());
217:                     }
218: 
219:                     return value;
220:                 }
221:             }
222:         } else if (value instanceof List<?> list) {
223:             List<Object> evaluatedlist = new ArrayList<>();
224: 
225:             for (Object item : list) {
226:                 evaluatedlist.add(evaluate(item, context));
227:             }
228: 
229:             return evaluatedlist;
230:         } else if (value instanceof Map<?, ?> map) {
231:             return evaluateInternal(map, context);
232:         }
233: 
234:         return value;
235:     }
236: 
237:     private Map<String, Object> evaluateInternal(Map<?, ?> map, Map<String, ?> context) {
238:         Map<String, Object> newMap = new LinkedHashMap<>();
239: 
240:         for (Entry<?, ?> entry : map.entrySet()) {
241:             newMap.put((String) entry.getKey(), evaluate(entry.getValue(), context));
242:         }
243: 
244:         return newMap;
245:     }
246: 
247:     private MethodResolver methodResolver() {
248:         return (ctx, target, name, args) -> {
249:             MethodExecutor executor = methodExecutorMap.get(name);
250: 
251:             if (executor == null) {
252:                 throw new UnsupportedOperationException("Method invocation is not allowed: " + name);
253:             }
254: 
255:             return executor;
256:         };
257:     }
258: 
259:     private static boolean validateTextExpression(String expression) {
260:         Matcher accessorMatcher = ACCESSOR_EXPRESSION_PATTERN.matcher(expression);
261: 
262:         while (accessorMatcher.find()) {
263:             String accessorContent = accessorMatcher.group(1);
264: 
265:             Matcher validAccessorMatcher = VALID_ACCESSOR_PATTERN.matcher(accessorContent);
266: 
267:             if (!validAccessorMatcher.matches()) {
268:                 return false;
269:             }
270:         }
271: 
272:         return true;
273:     }
274: 
275:     private static boolean validateFormulaExpression(String expression) {
276:         Matcher formulaMatcher = FORMULA_EXPRESSION_PATTERN.matcher(expression);
277: 
278:         return formulaMatcher.matches();
279:     }
