895: 
896:                 Matcher matcher = ARRAY_INDEX_VALUE_PATTERN.matcher(arrays);
897: 
898:                 List<Integer> arrayIndexes = new ArrayList<>();
899: 
900:                 while (matcher.find()) {
901:                     arrayIndexes.add(Integer.parseInt(matcher.group(1)));
902:                 }
903: 
904:                 for (int j = 0; j < arrayIndexes.size(); j++) {
