113:         ProjectWorkflow projectWorkflow = projectFacade.addWorkflow(
114:             connectedUserProject.getProjectId(), StringUtils.isEmpty(definition) ? DEFAULT_DEFINITION : definition);
115: 
116:         ConnectedUserProjectWorkflow connectedUserProjectWorkflow = new ConnectedUserProjectWorkflow();
117: 
118:         connectedUserProjectWorkflow.setConnectedUserProjectId(connectedUserProject.getId());
119:         connectedUserProjectWorkflow.setProjectWorkflowId(projectWorkflow.getId());
