201:     @Override
202:     public void publishProjectWorkflow(String workflowReferenceCode, String description, Environment environment) {
203:         ConnectedUserProject connectedUserProject = checkConnectedUserProject(
204:             OptionalUtils.get(SecurityUtils.getCurrentUserLogin(), "User not found"), environment);
205: 
206:         String workflowId = projectWorkflowService
207:             .fetchProjectWorkflowId(connectedUserProject.getProjectId(), workflowReferenceCode)
208:             .orElseThrow(() -> new ConfigurationException(
209:                 "Workflow with workflowReferenceCode: %s not exist".formatted(workflowReferenceCode),
210:                 WorkflowErrorType.WORKFLOW_NOT_FOUND));
211: 
212:         int newProjectVersion = projectFacade.publishProject(connectedUserProject.getProjectId(), description, false);
213: 
214:         ProjectDeploymentWorkflow projectDeploymentWorkflow = new ProjectDeploymentWorkflow();
215: 
216:         projectDeploymentWorkflow.setInputs(Map.of());
217:         projectDeploymentWorkflow.setWorkflowId(workflowId);
218: 
219:         if (newProjectVersion == 2) {
220:             ProjectDeployment projectDeployment = new ProjectDeployment();
221: 
222:             projectDeployment.setEnabled(true);
223:             projectDeployment.setEnvironment(environment);
224: 
225:             ConnectedUser connectedUser = connectedUserService.getConnectedUser(
226:                 connectedUserProject.getConnectedUserId());
227: 
228:             projectDeployment.setName("EMBEDDED_" + connectedUser.getExternalId());
229: 
230:             projectDeployment.setProjectId(connectedUserProject.getProjectId());
231:             projectDeployment.setProjectVersion(1);
232: 
233:             projectDeploymentFacade.createProjectDeployment(
234:                 projectDeployment, List.of(projectDeploymentWorkflow), List.of());
235:         } else {
236:             long projectDeploymentId = projectDeploymentService.getProjectDeploymentId(
237:                 connectedUserProject.getProjectId(), environment);
238: 
239:             projectDeploymentFacade.updateProjectDeployment(projectDeploymentId, List.of(projectDeploymentWorkflow));
240:         }
241:     }
