235:     @Override
236:     public void publishProjectWorkflow(
237:         String externalUserId, String workflowReferenceCode, String description, Environment environment) {
238: 
239:         ConnectedUserProject connectedUserProject = checkConnectedUserProject(externalUserId, environment);
240: 
241:         String workflowId = projectWorkflowService
242:             .fetchLatestProjectWorkflowId(connectedUserProject.getProjectId(), workflowReferenceCode)
243:             .orElseThrow(() -> new ConfigurationException(
244:                 "Workflow with workflowReferenceCode: %s not exist".formatted(workflowReferenceCode),
245:                 WorkflowErrorType.WORKFLOW_NOT_FOUND));
246: 
247:         ProjectWorkflow projectWorkflow = projectWorkflowService.getWorkflowProjectWorkflow(workflowId);
248: 
249:         List<ProjectDeploymentWorkflowConnection> connections = workflowTestConfigurationService
250:             .fetchWorkflowTestConfiguration(workflowId)
251:             .map(WorkflowTestConfiguration::getConnections)
252:             .orElse(List.of())
253:             .stream()
254:             .map(connection -> new ProjectDeploymentWorkflowConnection(
255:                 connection.getConnectionId(), connection.getWorkflowConnectionKey(),
256:                 connection.getWorkflowNodeName()))
257:             .toList();
258: 
259:         int newProjectVersion = projectFacade.publishProject(connectedUserProject.getProjectId(), description, false);
260: 
261:         if (newProjectVersion == 2) {
262:             ProjectDeployment projectDeployment = new ProjectDeployment();
263: 
264:             projectDeployment.setEnabled(true);
265:             projectDeployment.setEnvironment(environment);
266: 
267:             ConnectedUser connectedUser = connectedUserService.getConnectedUser(
268:                 connectedUserProject.getConnectedUserId());
269: 
270:             projectDeployment.setName("EMBEDDED_" + connectedUser.getExternalId());
271: 
272:             projectDeployment.setProjectId(connectedUserProject.getProjectId());
273:             projectDeployment.setProjectVersion(1);
274: 
275:             projectDeploymentFacade.createProjectDeployment(projectDeployment, workflowId, connections);
276:         } else {
277:             projectDeploymentFacade.updateProjectDeployment(
278:                 connectedUserProject.getProjectId(), newProjectVersion - 1, workflowReferenceCode, connections,
279:                 environment);
280:         }
281: 
282:         connectedUserProjectWorkflowService.incrementWorkflowVersion(
283:             connectedUserProject.getId(), projectWorkflow.getId());
284:     }
