317:     private void checkWorkflowNodeConnection(
318:         String map, List<Connection> connections, ProjectWorkflow projectWorkflow, String workflowNodeName) {
319: 
320:         WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(map);
321: 
322:         connections.stream()
323:             .filter(connection -> Objects.equals(connection.getComponentName(), workflowNodeType.name()))
324:             .findFirst()
325:             .ifPresent(connection -> workflowTestConfigurationFacade.saveWorkflowTestConfigurationConnection(
326:                 projectWorkflow.getWorkflowId(), workflowNodeName, workflowNodeType.name(),
327:                 connection.getId()));
328:     }
