330:     private void checkWorkflowNodeConnections(
331:         Map<String, ?> workflowMap, List<Connection> connections, ProjectWorkflow projectWorkflow) {
332: 
333:         List<Map<String, ?>> triggers = MapUtils.getList(workflowMap, "triggers", new TypeReference<>() {}, List.of());
334: 
335:         for (Map<String, ?> triggerMap : triggers) {
336:             checkWorkflowNodeConnection(
337:                 MapUtils.getString(triggerMap, "type"), connections, projectWorkflow,
338:                 MapUtils.getString(triggerMap, "name"));
339:         }
340: 
341:         List<Map<String, ?>> tasks = MapUtils.getList(workflowMap, "tasks", new TypeReference<>() {}, List.of());
342: 
343:         for (Map<String, ?> taskMap : tasks) {
344:             checkWorkflowNodeConnection(
345:                 MapUtils.getString(taskMap, "type"), connections, projectWorkflow, MapUtils.getString(taskMap, "name"));
346:         }
347:     }
